/* AI_PATCH_COMMERCE_PHASES4_7_MASTER_V1_START */
Route::prefix('commerce/v2/sites/{site}')
    ->middleware([
        \App\Http\Middleware\Commerce\CommerceApiExceptionBoundary::class,
        \App\Http\Middleware\Commerce\ResolveCommerceSiteContext::class,
    ])
    ->group(function () {
        Route::get('/attribution/resolve/{token}', [
            \App\Http\Controllers\Api\Commerce\V2\CommerceAttributionController::class,
            'resolve',
        ])->where('token', 'att_[A-Za-z0-9]{32,100}');

        Route::post('/attribution/events', [
            \App\Http\Controllers\Api\Commerce\V2\CommerceAttributionController::class,
            'record',
        ]);

        Route::get('/discover', [
            \App\Http\Controllers\Api\Commerce\V2\CommerceDiscoverController::class,
            'index',
        ]);

        Route::get('/discover/rules', [
            \App\Http\Controllers\Api\Commerce\V2\CommerceDiscoverController::class,
            'rules',
        ]);

        Route::middleware([
            \App\Http\Middleware\Commerce\ResolveCommerceCustomerSession::class,
        ])->group(function () {
            Route::post('/checkout/quotes', [
                \App\Http\Controllers\Api\Commerce\V2\CommerceCheckoutQuoteController::class,
                'create',
            ]);

            Route::get('/checkout/quotes/{quote}', [
                \App\Http\Controllers\Api\Commerce\V2\CommerceCheckoutQuoteController::class,
                'show',
            ])->where('quote', 'qt_[A-Za-z0-9]+');

            Route::post('/orders', [
                \App\Http\Controllers\Api\Commerce\V2\CommerceOrderController::class,
                'store',
            ]);

            Route::get('/customer/orders', [
                \App\Http\Controllers\Api\Commerce\V2\CommerceOrderController::class,
                'index',
            ]);

            Route::get('/customer/orders/{order}', [
                \App\Http\Controllers\Api\Commerce\V2\CommerceOrderController::class,
                'show',
            ])->where('order', 'ord_[A-Za-z0-9]+');

            Route::delete('/customer/orders/{order}', [
                \App\Http\Controllers\Api\Commerce\V2\CommerceOrderController::class,
                'cancel',
            ])->where('order', 'ord_[A-Za-z0-9]+');
        });
    });
/* AI_PATCH_COMMERCE_PHASES4_7_MASTER_V1_END */
ROUTE_BLOCK

    export COMMERCE_API_ROUTES='routes/api.php'
    export COMMERCE_ROUTE_BLOCK_FILE="$ROUTE_BLOCK_FILE"

    php <<'PHP'
<?php

$path = getenv('COMMERCE_API_ROUTES');
$blockPath = getenv('COMMERCE_ROUTE_BLOCK_FILE');
$source = file_get_contents($path);
$block = file_get_contents($blockPath);

if (! is_string($source) || ! is_string($block)) {
    fwrite(
        STDERR,
        "ERROR: Cannot read Commerce route source/block.\n"
    );
    exit(1);
}

$markers = [
    [
        '/* AI_PATCH_COMMERCE_QUOTE_SHIPPING_PHASE4_V1_START */',
        '/* AI_PATCH_COMMERCE_QUOTE_SHIPPING_PHASE4_V1_END */',
    ],
    [
        '/* AI_PATCH_COMMERCE_PHASES4_7_MASTER_V1_START */',
        '/* AI_PATCH_COMMERCE_PHASES4_7_MASTER_V1_END */',
    ],
];

foreach ($markers as [$start, $end]) {
    $startCount = substr_count($source, $start);
    $endCount = substr_count($source, $end);

    if ($startCount !== $endCount || $startCount > 1) {
        fwrite(
            STDERR,
            "ERROR: Commerce route marker imbalance.\n"
        );
        exit(1);
    }

    if ($startCount === 1) {
        $pattern = '/'
            . preg_quote($start, '/')
            . '.*?'
            . preg_quote($end, '/')
            . '/s';
        $source = preg_replace(
            $pattern,
            '',
            $source,
            1,
            $count
        );

        if (! is_string($source) || $count !== 1) {
            fwrite(
                STDERR,
                "ERROR: Cannot remove old Commerce route block.\n"
            );
            exit(1);
        }
    }
}

$patched = rtrim($source)
    . "\n\n"
    . trim($block)
    . "\n";

$written = file_put_contents($path, $patched);

if ($written === false || $written !== strlen($patched)) {
    fwrite(
        STDERR,
        "ERROR: Cannot write routes/api.php.\n"
    );
    exit(1);
}
PHP

    rm -f "$ROUTE_BLOCK_FILE"

