    fi

    artisan_safe optimize:clear

    php <<'PHP'
<?php

require getcwd() . '/vendor/autoload.php';
$app = require getcwd() . '/bootstrap/app.php';
$app->make(
    Illuminate\Contracts\Console\Kernel::class
)->bootstrap();

$expected = [
    'api/commerce/v2/sites/{site}/checkout/quotes',
    'api/commerce/v2/sites/{site}/orders',
    'api/commerce/v2/sites/{site}/customer/orders',
    'api/commerce/v2/sites/{site}/attribution/resolve/{token}',
    'api/commerce/v2/sites/{site}/discover',
    'api/commerce/v2/sites/{site}/discover/rules',
];

$found = [];

foreach ($app['router']->getRoutes() as $route) {
    if (in_array($route->uri(), $expected, true)) {
        $found[$route->uri()] = true;
    }
}

$missing = array_values(array_diff(
    $expected,
    array_keys($found)
));

if ($missing !== []) {
    fwrite(
        STDERR,
        'ERROR: Missing ERP routes: '
        . implode(', ', $missing)
        . PHP_EOL
    );
    exit(1);
}

echo "ERP_PHASES4_7_TARGETED_ROUTE_DISCOVERY=PASS\n";
PHP

