STOREFRONT_MASTER_B64_21

    for FILE in "${FILES[@]}"; do
        if [[ "$FILE" == *.php ]]; then
            php -l "$FILE"
        fi
    done

    grep -Fq \
      "Route::get('/go/{token}'" \
      routes/commerce_v2.php

    grep -Fq \
      "Route::post('/orders'" \
      routes/commerce_v2.php

    grep -Fq \
      "Route::get('/discover'" \
      routes/commerce_v2.php

    grep -Fq \
      '@if(isset($errors) && $errors->any())' \
      resources/views/commerce_v2/layouts/app.blade.php

    artisan_safe optimize:clear
    artisan_safe view:cache
    artisan_safe view:clear

    php <<'PHP'
<?php

require getcwd() . '/vendor/autoload.php';
$app = require getcwd() . '/bootstrap/app.php';
$app->make(
    Illuminate\Contracts\Console\Kernel::class
)->bootstrap();

$expectedNames = [
    'commerce.v2.attribution.go',
    'commerce.v2.checkout.index',
    'commerce.v2.checkout.confirm',
    'commerce.v2.orders.store',
    'commerce.v2.orders.index',
    'commerce.v2.orders.show',
    'commerce.v2.discover',
];

$missing = collect($expectedNames)
    ->reject(
        fn ($name) => Illuminate\Support\Facades\Route::has(
            $name
        )
    )
    ->values()
    ->all();

if ($missing !== []) {
    fwrite(
        STDERR,
        'ERROR: Missing Storefront routes: '
        . implode(', ', $missing)
        . PHP_EOL
    );
    exit(1);
}

echo "STOREFRONT_PHASES4_7_TARGETED_ROUTE_DISCOVERY=PASS\n";
PHP

    for COMMAND in \
      'commerce-v2:checkout-foundation-smoke' \
      'commerce-v2:phases4-7-smoke'
    do
        artisan_safe list --raw \
          | grep -E "^${COMMAND}([[:space:]]|$)" \
          >/dev/null
    done

    trap - ERR

    printf '%s\n' \
      'LINXEN_COMMERCE_PHASES4_7_STOREFRONT_SOURCE_PATCH=PASS'
    printf '%s\n' 'STOREFRONT_DB_MUTATION=NONE'
    printf '%s\n' 'PATCH_ERP_API_CALL=NONE'
    printf '%s\n' 'CUSTOMER_TOKEN_BROWSER_EXPOSURE=NO'
    printf '%s\n' 'ORDER_IDEMPOTENCY_SESSION=YES'
    printf '%s\n' \
      'ATTRIBUTION_TOKEN_SESSION=FIRST_AND_LAST'
    printf '%s\n' \
      'CHECKOUT_LOCAL_ORDER=IMPLEMENTED_BUT_DB_GATED'
    printf '%s\n' 'KIOTVIET_WRITE=ERP_OUTBOX_ONLY'
    printf '%s\n' 'DISCOVER_ROUTE=/v2/discover'
    printf '%s\n' 'ATTRIBUTION_ROUTE=/go/{token}'
    printf '%s\n' 'NPM_BUILD=NOT_REQUIRED'
    printf '%s\n' 'V1_STOREFRONT=UNCHANGED'
    printf 'BACKUP_DIR=%s\n' "$BACKUP_ROOT"

    exit 0
fi
